typedef unsigned char u_char;
typedef unsigned int u_int;
typedef unsigned long u_long;

class nglFixedString
{
public:
  typedef u_long fint;
  enum { FINT_SIZE = 8, STR_SIZE = 32, NUM_FINTS = STR_SIZE / FINT_SIZE };

  fint* value() { return reinterpret_cast<fint*>(str); }
  const fint* value() const { return reinterpret_cast<const fint*>(str); }

  const nglFixedString& operator=(const nglFixedString& rhs)
  {
    for (int i = 0; i < NUM_FINTS; ++i)
      value()[i] = rhs.value()[i];
    return *this;
  }

  const char* c_str() const { return str; }

private:
  char str[STR_SIZE];
};

class nglInstanceBank
{
public:
  struct Instance
  {
    nglFixedString Key;
    void* Value;
    int RefCount;
    Instance* Forward[1];
  };

  Instance* Search(const nglFixedString& Key);
  Instance* Insert(const nglFixedString& Key, void* Value);
};

struct nglFileBuf
{
  u_char* Buf;
  u_int Size;
  u_int UserData;
};

struct nglMesh;

struct nglMeshFile
{
  nglFixedString FileName;
  char FilePath[256];
  nglFileBuf FileBuf;
  bool LoadedInPlace;
  nglMesh* FirstMesh;
};

extern nglInstanceBank nglMeshFileBank;
extern char nglMeshPath[256];
extern char nglWork[512];

extern "C" char* strcpy(char*, const char*);
extern "C" char* strcat(char*, const char*);

void* nglMemAlloc(u_int Size, u_int Align = 1);
void nglMemFree(void* Ptr);
bool nglReadFile(const char* FileName, nglFileBuf* File, u_int Align);
void nglReleaseFile(nglFileBuf* File);
void nglWarning(const char* Format, ...);
bool nglLoadMeshFileInternal(const nglFixedString& FileName, nglMeshFile* MeshFile);

bool nglLoadMeshFile(const nglFixedString& FileName)
{
  nglInstanceBank::Instance* Inst;
  if ((Inst = nglMeshFileBank.Search(FileName)))
  {
    Inst->RefCount++;
    return true;
  }

  strcpy(nglWork, nglMeshPath);
  strcat(nglWork, FileName.c_str());
  strcat(nglWork, ".ps2mesh");

  nglMeshFile* MeshFile = (nglMeshFile*)nglMemAlloc(sizeof(nglMeshFile));
  strcpy(MeshFile->FilePath, nglMeshPath);
  MeshFile->FileName = FileName;
  MeshFile->LoadedInPlace = false;

  if (!nglReadFile(nglWork, &MeshFile->FileBuf, 128))
  {
    nglWarning("nglLoadMeshFile: Unable to open %s%s.\n", nglMeshPath, FileName.c_str());
    nglMemFree(MeshFile);
    return false;
  }

  bool Result = nglLoadMeshFileInternal(FileName, MeshFile);
  if (!Result)
  {
    nglReleaseFile(&MeshFile->FileBuf);
    nglMemFree(MeshFile);
    return false;
  }

  nglMeshFileBank.Insert(FileName, MeshFile);
  return true;
}
